\\u0443\\u0435\\u0442. \\u0422.\\u0435. GPU-\\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c\\u0430 \\u043d\\u0435\\u0442 \\u043d\\u0435\\u0441\\u043c\\u043e\\u0442\\u0440\\u044f \\u043d\\u0430 \\u043f\\u0430\\u043f\\u043a\\u0443 cuda.\\n- \\u0421\\u0435\\u0442\\u044c: `urllib(urlopen github/pypi, timeout=4)` \\u2192 `URLError`; \\u0441\\u0435\\u0442\\u044c \\u0432\\u044b\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430, pip \\u043d\\u0438\\u0447\\u0435\\u0433\\u043e \\u043d\\u0435 \\u0441\\u043a\\u0430\\u0447\\u0430\\u0435\\u0442.\\n- \\u0420\\u0435\\u0441\\u0443\\u0440\\u0441\\u044b \\u0435\\u0441\\u0442\\u044c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e CPU: 224 \\u044f\\u0434\\u0440\\u0430, 2 TiB RAM, 0 swap. Git \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d (2.53.0).\\n\\n\\u0418\\u0442\\u043e\\u0433 \\u0431\\u043b\\u043e\\u043a\\u0430 1: \\u044d\\u0442\\u043e \\u0447\\u0438\\u0441\\u0442\\u0430\\u044f design-only \\u043f\\u0435\\u0441\\u043e\\u0447\\u043d\\u0438\\u0446\\u0430. \\u0414\\u043b\\u044f \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 \\u043d\\u0443\\u0436\\u043d\\u0430 \\u0446\\u0435\\u043b\\u0435\\u0432\\u0430\\u044f \\u0441\\u0440\\u0435\\u0434\\u0430 (GPU + \\u0441\\u0435\\u0442\\u044c): \\u043a\\u043b\\u043e\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c spcl/QuaRot (\\u043f\\u0438\\u043d \\u043a\\u043e\\u043c\\u043c\\u0438\\u0442\\u0430), \\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u0442\\u044c torch/transformers \\u0441 Phi\\u22123-\\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u043e\\u0439, \\u0441\\u043a\\u0430\\u0447\\u0430\\u0442\\u044c \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0438 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b. \\u0417\\u0434\\u0435\\u0441\\u044c \\u043c\\u043e\\u0436\\u043d\\u043e \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0441\\u043f\\u0440\\u043e\\u0435\\u043a\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0438 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043a\\u043e\\u043d\\u0442\\u0440\\u0430\\u043a\\u0442\\u044b \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438.\\n\\n## \\u0411\\u043b\\u043e\\u043a 2 \\u2014 \\u0427\\u0435\\u0440\\u043d\\u043e\\u0432\\u0438\\u043a \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0430 (draft, \\u043d\\u0435 \\u043f\\u043e\\u043b\\u043d\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435)\\n\\n**\\u0412\\u043e\\u043f\\u0440\\u043e\\u0441 \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u0435\\u043c \\u043a\\u0430\\u043a** \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0432\\u0443\\u0445 \\u043e\\u0441\\u0435\\u0439: (i) \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0432\\u0435\\u0441\\u043e\\u0432 w\\u2208{4,6,8}, (ii) \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440 quant\\u2208{RTN, GPTQ}, \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0430 QuaRot \\u043d\\u0430 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 Phi-3-mini-4k-instruct.\\n\\n- **\\u0423\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f (\\u044f\\u0447\\u0435\\u0439\\u043a\\u0438):** 2 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430 \\u00d7 3 \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 = 6 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439. \\u0414\\u043b\\u044f \\u0447\\u0438\\u0441\\u0442\\u043e\\u0442\\u044b: `--rotate --perhead` \\u0443 QuaRot \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u044b \\u0434\\u043b\\u044f \\u0412\\u0421\\u0415\\u0425 6 \\u044f\\u0447\\u0435\\u0435\\u043a (\\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u00ab\\u043a\\u0430\\u043a QuaRot \\u043e\\u0431\\u043e\\u0431\\u0449\\u0430\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430 Phi-3\\u00bb), \\u0433\\u0440\\u0443\\u043f\\u043f\\u044b \\u0432\\u0435\\u0441\\u043e\\u0432 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b (\\u043d\\u0430\\u043f\\u0440. `--w_groupsize 128`), \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0438/KV \\u043d\\u0435 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0443\\u044e\\u0442\\u0441\\u044f (weight-only-\\u0440\\u0435\\u0436\\u0438\\u043c), \\u0447\\u0442\\u043e\\u0431\\u044b \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e weight-RTN vs weight-GPTQ.\\n- **\\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438:**\\n  - Perplexity: WikiText-2 \\u0438 C4 (`eval/get_ppl.py` \\u0432 QuaRot \\u043b\\u0438\\u0431\\u043e \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 `transformers.Perplexity`-\\u0441\\u0442\\u0438\\u043b\\u044c \\u0441\\u043e stride ~512, seq_len 2048) \\u2014 \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u044f\\u0447\\u0435\\u0435\\u043a.\\n  - Zero-shot accuracy: lm-evaluation-harness (\\u043f\\u0438\\u043d \\u043a\\u043e\\u043c\\u043c\\u0438\\u0442\\u0430) \\u2014 \\u0442\\u0430\\u0441\\u043a\\u0438 arc_easy, arc_challenge, hellaswag, piqa, openbookqa, boolq, winogrande \\u2192 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u0431\\u0430\\u043b\\u043b (mean acc). \\u0422.\\u043a. \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c instruct, \\u0434\\u043b\\u044f zero-shot \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0442\\u044c \\u0435\\u0451 chat-template (\\u0438\\u043b\\u0438 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0448\\u0430\\u0431\\u043b\\u043e\\u043d\\u0430 \\u2014 \\u043e\\u0442\\u043c\\u0435\\u0442\\u0438\\u0442\\u044c \\u0432 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0435).\\n- **\\u041f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d RTN/GPTQ:** \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 `quantize.py` QuaRot \\u0441 \\u0430\\u0440\\u0433\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u043c \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430 (\\u0432 QuaRot \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442\\u0441\\u044f `--quantizer {gptq, rtn}`/\\u0430\\u043d\\u0430\\u043b\\u043e\\u0433 \\u2014 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 \\u0438\\u043c\\u044f \\u0444\\u043b\\u0430\\u0433\\u0430 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u043c \\u043f\\u043e \\u043f\\u0438\\u043d\\u0443): GPTQ \\u2014 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 \\u043d\\u0430 C4 (nsamples 128\\u2026256), RTN \\u2014 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0438 \\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442, \\u043d\\u043e \\u0434\\u043b\\u044f \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0438 \\u0433\\u043e\\u043d\\u044f\\u0435\\u043c \\u0441 \\u0442\\u0435\\u043c \\u0436\\u0435 seed/\\u0442\\u0435\\u043c\\u0438 \\u0436\\u0435 \\u0441\\u044d\\u043c\\u043f\\u043b\\u0430\\u043c\\u0438; \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u043c \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0447\\u0435\\u043a\\u0438 \\u0432 `--save`, \\u0437\\u0430\\u0442\\u0435\\u043c \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0439 eval \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445.\\n- **\\u0411\\u0435\\u0439\\u0437\\u043b\\u0430\\u0439\\u043d\\u044b:** (1) FP16 full-precision \\u2014 \\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 reference; (2) INT8-\\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 (wbits=8, groupsize=-1 \\u0438\\u043b\\u0438 torch-\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 INT8) \\u043a\\u0430\\u043a \\u0431\\u043b\\u0438\\u0436\\u0430\\u0439\\u0448\\u0430\\u044f \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u0430; FP8 \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0435\\u0441\\u043b\\u0438 \\u043e\\u0431\\u043d\\u0430\\u0440\\u0443\\u0436\\u0435\\u043d \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0432 \\u043f\\u0438\\u043d\\u0435 (\\u0432 QuaRot \\u043d\\u0435\\u0442 FP8 \\u0438\\u0437 \\u043a\\u043e\\u0440\\u043e\\u0431\\u043a\\u0438 \\u2014 \\u044d\\u0442\\u043e \\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442 \\u0432 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435).\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438:** \\u0444\\u0438\\u043a\\u0441. seed (`--seed 2` \\u043a\\u0430\\u043a \\u0443 QuaRot), \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0439 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0441\\u044d\\u043c\\u043f\\u043b \\u0434\\u043b\\u044f RTN \\u0438 GPTQ, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0435 eval-\\u0441\\u0438\\u043a\\u0432\\u0435\\u043d\\u0441\\u044b/stride, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0439 groupsize, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0435 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 torch/transformers/QuaRot-commit/lm-eval-commit, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u043e\\u0435 \\u0436\\u0435\\u043b\\u0435\\u0437\\u043e; \\u0434\\u043b\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442-\\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u2014 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0444\\u043e\\u0440\\u043c\\u0430\\u0442 \\u0448\\u0430\\u0431\\u043b\\u043e\\u043d\\u0430 (chat \\u0438\\u043b\\u0438 raw) \\u043a\\u0430\\u043a \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0443\\u044e \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430, \\u043d\\u0435 \\u043c\\u0435\\u043d\\u044f\\u044f \\u0432 \\u0441\\u0435\\u0440\\u0435\\u0434\\u0438\\u043d\\u0435.\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b:** \\u043f\\u0440\\u043e\\u0433\\u043d\\u0430\\u0442\\u044c \\u0442\\u0443 \\u0436\\u0435 \\u0440\\u0435\\u0448\\u0451\\u0442\\u043a\\u0443 \\u043d\\u0430 LLaMA-2-7B (\\u044d\\u0442\\u0430\\u043b\\u043e\\u043d \\u0438\\u0437 \\u0431\\u0443\\u043c\\u0430\\u0433\\u0438 QuaRot) \\u0438 \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u0441 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u043c\\u0438 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f\\u043c\\u0438 \\u2014 \\u044d\\u0442\\u043e \\u0432\\u0430\\u043b\\u0438\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442, \\u0447\\u0442\\u043e \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0430\\u0446\\u0438\\u044f (\\u0438\\u043b\\u0438 \\u0435\\u0451 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0438\\u0435) \\u0443 Phi-3 \\u2014 \\u0441\\u0432\\u043e\\u0439\\u0441\\u0442\\u0432\\u043e \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438, \\u0430 \\u043d\\u0435 \\u0441\\u043b\\u043e\\u043c\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0430.\\n- **\\u0412\\u044b\\u0445\\u043e\\u0434:** \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 6 \\u044f\\u0447\\u0435\\u0435\\u043a \\u00d7 {PPL(wikitext2), PPL(c4), mean zero-shot + per-task} + \\u0431\\u0435\\u0439\\u0437\\u043b\\u0430\\u0439\\u043d\\u044b, \\u043f\\u043b\\u044e\\u0441 delta-vs-FP16; \\u0432\\u044b\\u0432\\u043e\\u0434 \\u043e \\u0442\\u043e\\u043c, \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043b\\u0438 \\u043f\\u0440\\u0435\\u0438\\u043c\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u043e GPTQ \\u043d\\u0430\\u0434 RTN \\u043d\\u0430 Phi-3 \\u0438 \\u043d\\u0430\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u043e\\u043d\\u043e \\u0443\\u0441\\u0442\\u043e\\u0439\\u0447\\u0438\\u0432\\u043e \\u043f\\u043e \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u044f\\u043c.\\n\\n## \\u0411\\u043b\\u043e\\u043a 3 \\u2014 \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438, \\u0432\\u043b\\u0438\\u044f\\u044e\\u0449\\u0438\\u0435 \\u043d\\u0430 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\n\\n1. **\\u0420\\u0435\\u0441\\u0443\\u0440\\u0441\\u044b/\\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c.** \\u0417\\u0434\\u0435\\u0441\\u044c \\u043d\\u0435\\u0442 GPU \\u0438 \\u0441\\u0435\\u0442\\u0438; \\u0442\\u0430\\u0439\\u043c\\u0438\\u043d\\u0433\\u0438 \\u043d\\u0435\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u044b. GPTQ-\\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 \\u043d\\u0430 CPU (\\u0434\\u0430\\u0436\\u0435 224 \\u044f\\u0434\\u0440\\u0430/2TiB) \\u0434\\u043b\\u044f 3.8B \\u043a\\u0440\\u0430\\u0439\\u043d\\u0435 \\u043c\\u0435\\u0434\\u043b\\u0435\\u043d\\u043d\\u0430; CPU-\\u0438\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 fp16-\\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u0434\\u043b\\u044f PPL \\u0440\\u0435\\u0430\\u043b\\u0435\\u043d, \\u043d\\u043e zero-shot \\u043d\\u0430 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u0445 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430\\u0445 \\u043d\\u0430 CPU \\u2014 \\u0441\\u043f\\u043e\\u0440\\u043d\\u043e \\u043f\\u043e \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438. \\u2192 \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435: \\u0446\\u0435\\u043b\\u0435\\u0432\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u043d\\u0430 \\u043e\\u0434\\u043d\\u043e\\u0439 GPU (\\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u043e\\u0436\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u226540\\u0413\\u0411) + \\u0441\\u0435\\u0442\\u044c; \\u0437\\u0434\\u0435\\u0441\\u044c \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d. \\u041d\\u0443\\u0436\\u043d\\u043e \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438 \\u0438 \\u043e\\u0442\\u0441\\u0435\\u0447\\u043a\\u0443, \\u043f\\u0440\\u0438 \\u043a\\u043e\\u0442\\u043e\\u0440\\u043e\\u0439 \\u0431\\u0435\\u0440\\u0451\\u043c \\u043c\\u0435\\u043d\\u044c\\u0448\\u0435 zero-shot \\u0441\\u044d\\u043c\\u043f\\u043b\\u043e\\u0432.\\n2. **\\u0420\\u0430\\u0437\\u043c\\u0435\\u0440 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043e\\u0447\\u043d\\u043e\\u0433\\u043e \\u0441\\u0435\\u0442\\u0430.** \\u0414\\u0435\\u0444\\u043e\\u043b\\u0442 QuaRot/GPTQ \\u2014 nsamples\\u2248128 (C4); \\u0443\\u0432\\u0435\\u043b\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0434\\u043e 768 \\u0441\\u0442\\u0430\\u0431\\u0438\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u0435\\u0442 GPTQ, \\u043d\\u043e \\u0434\\u043e\\u0440\\u043e\\u0436\\u0435; RTN \\u043a \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0435 \\u043d\\u0435\\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u0435\\u043d \\u2192 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0430 \\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u043d\\u0430 \\u0440\\u0430\\u0437\\u0431\\u0440\\u043e\\u0441 PPL \\u0438 \\u043d\\u0430 \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f. \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435: \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u0444\\u0438\\u043a\\u0441. \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440 \\u0438 \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u0441\\u044d\\u043c\\u043f\\u043b \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0438\\u0445 \\u0432\\u0435\\u0442\\u043e\\u043a, \\u0447\\u0442\\u043e\\u0431\\u044b \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0430 \\u0431\\u044b\\u043b\\u0430 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0435.\\n3. **Phi-3 vs LLaMA (\\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430).** Phi-3-mini-4k-instruct \\u2014 `Phi3ForCausalLM`: hidden_size 3072 (\\u041d\\u0415 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c 2 \\u2014 \\u043a\\u0430\\u043a QuaRot \\u0441\\u0442\\u0440\\u043e\\u0438\\u0442 \\u0425\\u0430\\u0434\\u0430\\u043c\\u0430\\u0440-\\u0431\\u043b\\u043e\\u043a\\u0438? \\u0444\\u043e\\u043b\\u0431\\u044d\\u043a truncate/\\u0434\\u0432\\u043e\\u0439\\u043d\\u043e\\u0439 \\u0425\\u0430\\u0434\\u0430\\u043c\\u0430\\u0440), head_dim 96 (\\u043d\\u0435 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c 2), rotary (Phi3RotaryEmbedding, theta 10000), MHA 32/32 (\\u0431\\u0435\\u0437 GQA), sliding-window attention window=2047 (\\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u043d\\u0430 \\u043c\\u0430\\u0441\\u043a\\u0443 \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438 \\u043f\\u0430\\u0442\\u0447\\u0435 QuaRot-\\u043e\\u043c attention), \\u0430\\u0442\\u0440\\u0438\\u0431\\u0443\\u0442\\u044b q/k/v/o_proj \\u0431\\u043b\\u0438\\u0437\\u043a\\u0438 \\u043a LLaMA (\\u0432\\u0435\\u0440\\u043e\\u044f\\u0442\\u043d\\u043e \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d \\u0437\\u0430\\u0432\\u0435\\u0434\\u0451\\u0442\\u0441\\u044f, \\u043d\\u043e \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0432 \\u0444\\u043e\\u0440\\u043a\\u0435 transformers \\u0438 \\u0432 rotate_llama \\u2014 \\u043f\\u043e\\u0434 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u043e\\u043c). \\u2192 \\u041d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c, \\u043a\\u043e\\u0442\\u043e\\u0440\\u0443\\u044e \\u043d\\u0430\\u0434\\u043e \\u0437\\u0430\\u043a\\u0440\\u044b\\u0442\\u044c \\u043d\\u0430 \\u044d\\u0442\\u0430\\u043f\\u0435 \\u0440\\u0430\\u0437\\u0432\\u0435\\u0434\\u043a\\u0438 \\u043a\\u043e\\u0434\\u0430: \\u00ab\\u043f\\u043e\\u0434\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442\\u0441\\u044f \\u043b\\u0438 QuaRot \\u043d\\u0430 Phi3 \\u0431\\u0435\\u0437 \\u043c\\u043e\\u0434\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0439\\u00bb.\\n4. **\\u041f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 6-\\u0431\\u0438\\u0442.** GPTQ-\\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440 QuaRot \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043e \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 (wbits\\u2208[2,8], \\u043a\\u0430\\u043a \\u0432 GPTQ-for-LLaMa), \\u0442.\\u0435. 6-\\u0431\\u0438\\u0442 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442; \\u043d\\u043e \\u044d\\u0442\\u043e \\u0432\\u043d\\u0435 \\u0441\\u043a\\u043e\\u0443\\u043f\\u0430 \\u0431\\u0443\\u043c\\u0430\\u0433\\u0438 \\u0438 \\u0432\\u043d\\u0435 README-\\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u043e\\u0432 \\u2192 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u0442\\u044c \\u043d\\u0430 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435 QuantLinear (\\u0443\\u043f\\u0430\\u043a\\u043e\\u0432\\u043a\\u0430 6-\\u0431\\u0438\\u0442 \\u0432 int32/int64, \\u0433\\u0440\\u0443\\u043f\\u043f\\u044b) \\u0438 \\u0447\\u0438\\u0441\\u043b\\u043e\\u0432\\u0443\\u044e \\u0441\\u0442\\u0430\\u0431\\u0438\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c. 8-\\u0431\\u0438\\u0442 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u0438\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a wbits=8.\\n5. **Zero-shot \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438.** \\u041e\\u0442\\u043a\\u0443\\u0434\\u0430 \\u0431\\u0440\\u0430\\u0442\\u044c: lm-eval-harness (\\u043f\\u0438\\u043d). \\u0411\\u0435\\u0437 \\u0441\\u0435\\u0442\\u0438 harness \\u043d\\u0443\\u0436\\u043d\\u043e \\u0437\\u0430\\u0432\\u0435\\u0442\\u0434\\u043e\\u0440\\u0438\\u0442\\u044c \\u0432 \\u043e\\u0431\\u0440\\u0430\\u0437. \\u0424\\u043e\\u0440\\u043c\\u0430\\u0442 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u0430 \\u0434\\u043b\\u044f instruct-\\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u043c\\u0435\\u043d\\u044f\\u0435\\u0442 \\u0446\\u0438\\u0444\\u0440\\u044b \\u2192 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c. \\u0412\\u0430\\u043b\\u0438\\u0434\\u043d\\u043e\\u0441\\u0442\\u044c \\u043d\\u0430 CPU \\u2014 \\u043f\\u043e\\u0434 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u043e\\u043c (\\u0441\\u043c. \\u043f.1).\\n6. **\\u0411\\u0435\\u0439\\u0437\\u043b\\u0430\\u0439\\u043d\\u044b.** FP16 \\u2014 \\u0431\\u0435\\u0441\\u0441\\u043f\\u043e\\u0440\\u043d\\u044b\\u0439 reference; FP8 \\u0438\\u0437 \\u043a\\u043e\\u0440\\u043e\\u0431\\u043a\\u0438 \\u0432 QuaRot \\u043d\\u0435\\u0442 \\u2014 \\u043b\\u0438\\u0431\\u043e \\u044f\\u0432\\u043d\\u043e \\u043e\\u0442\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u043c\\u0441\\u044f \\u043e\\u0442 FP8, \\u043b\\u0438\\u0431\\u043e \\u043f\\u043e\\u0434\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u043c \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 (\\u043d\\u043e\\u0432\\u0430\\u044f \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c). INT8-\\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c \\u043a\\u0430\\u043a wbits=8 \\u0431\\u0435\\u0437 \\u0433\\u0440\\u0443\\u043f\\u043f.\\n7. **\\u0412\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c/\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438.** \\u041d\\u0443\\u0436\\u0435\\u043d \\u043f\\u0438\\u043d transformers \\u0441 `Phi3ForCausalLM` (\\u2265~4.40), \\u043f\\u0438\\u043d QuaRot-\\u043a\\u043e\\u043c\\u043c\\u0438\\u0442\\u0430, \\u043f\\u0438\\u043d lm-eval, \\u0441\\u0435\\u043c\\u0435\\u043d\\u0430; \\u0431\\u0435\\u0437 \\u044d\\u0442\\u043e\\u0433\\u043e \\u0437\\u0430\\u044f\\u0432\\u043b\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f \\u043d\\u0435 \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u044b.\\n\\n\\u042d\\u0442\\u0438 \\u043f\\u0443\\u043d\\u043a\\u0442\\u044b \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u044e \\u044f\\u0432\\u043d\\u043e \\u0437\\u0430\\u043a\\u0440\\u044b\\u0442\\u044c \\u0434\\u043e \\u0444\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 (stage=result). \\u041f\\u043e\\u043b\\u043d\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0435\\u0449\\u0451 \\u043d\\u0435 \\u0432\\u044b\\u0434\\u0430\\u044e \\u2014 \\u0436\\u0434\\u0443 \\u043e\\u0434\\u043e\\u0431\\u0440\\u0435\\u043d\\u0438\\u044f/\\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u0439 \\u043f\\u043e \\u0447\\u0435\\u0440\\u043d\\u043e\\u0432\\u0438\\u043a\\u0443.\\n\", \"evidence\": \"\\n\\u041a\\u043e\\u043c\\u0430\\u043d\\u0434\\u044b \\u0438 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u0438\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u0438 (\\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u044b \\u0432 \\u043f\\u0435\\u0441\\u043e\\u0447\\u043d\\u0438\\u0446\\u0435):\\n1) `ls -la /workspace` \\u2192 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e `task.json`; `find /workspace -maxdepth 2` \\u2192 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a\\u043e\\u0440\\u0435\\u043d\\u044c. \\u041a\\u043e\\u0434\\u0430 QuaRot, scripts/, configs/, eval-\\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u043e\\u0432, \\u0437\\u0430\\u043c\\u0435\\u0442\\u043e\\u043a \\u043f\\u0440\\u043e Phi-3 \\u0438\\u043b\\u0438 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 \\u0431\\u0438\\u0431\\u043b\\u0438\\u043e\\u0442\\u0435\\u043a \\u041d\\u0415\\u0422.\\n2) `cat /workspace/task.json` \\u2192 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 + context \\u00abDesign-only task; repositories and compute are not required\\u00bb; environments: network=disabled, gpu_enabled=false, datasets: [], cpu_affinity_count=224.\\n3) `python3 --version` \\u2192 3.14.4; `pip3 list` \\u2192 \\u041d\\u0415\\u0422 torch/transformers/numpy/datasets/accelerate/lm_eval (ML-\\u0441\\u0442\\u0435\\u043a \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442; grep \\u043f\\u043e \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u043c \\u0441\\u043b\\u043e\\u0432\\u0430\\u043c \\u043f\\u0443\\u0441\\u0442, exit 1).\\n4) GPU: `ls /dev/nvidia*` \\u2192 \\u00abno nvidia dev\\u00bb; `nvidia-smi` \\u2192 \\u00abcould not communicate with NVIDIA driver\\u00bb; `/usr/local/cuda` \\u2014 \\u043f\\u0443\\u0441\\u0442\\u0430\\u044f \\u0434\\u0438\\u0440\\u0435\\u04