\\u0447\\u0442\\u043e\\u0431\\u044b \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0435\\u0441\\u043e\\u0432\\u044b\\u0445 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u043e\\u0432.\", \"Phi-3-mini-4k-instruct \\u043a\\u0430\\u043a \\u0435\\u0441\\u0442\\u044c (instruct): \\u0434\\u043b\\u044f zero-shot \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0435\\u0451 chat-template, \\u0447\\u0442\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0432 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0435.\", \"\\u0411\\u0435\\u0439\\u0437\\u043b\\u0430\\u0439\\u043d FP16 \\u2014 \\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 reference; INT8-\\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 = wbits=8 \\u0431\\u0435\\u0437 \\u0433\\u0440\\u0443\\u043f\\u043f; FP8 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0440\\u0438 \\u043e\\u0431\\u043d\\u0430\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0438 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u044e\\u0449\\u0435\\u0433\\u043e \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0430 \\u0432 \\u043f\\u0438\\u043d\\u0435 QuaRot.\"], \"uncertainties\": [\"\\u0420\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c/\\u0440\\u0435\\u0441\\u0443\\u0440\\u0441\\u044b: \\u0441\\u043a\\u043e\\u0440\\u043e\\u0441\\u0442\\u044c GPTQ-\\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0438 \\u043d\\u0430 CPU \\u0438 \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c GPU; \\u0442\\u0430\\u0439\\u043c\\u0438\\u043d\\u0433\\u0438 \\u043d\\u0435\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u044b \\u2014 \\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u043d\\u0430 \\u0432\\u0